mapper.select:
SELECT t.*, u.nick_name AS creator_name, u.user_name AS creator_user_name,
       d.dept_name, IF(t.update_time IS NOT NULL AND t.update_time > t.create_time,1,0) AS edited
FROM biz_research_topic t
LEFT JOIN sys_user u ON u.user_id=t.creator_id
LEFT JOIN sys_dept d ON d.dept_id=t.dept_id
WHERE t.del_flag='0'
AND t.topic_type=#{topicType}
AND t.creator_id=#{authorId}
AND t.create_time >= #{beginTime}
AND t.create_time <= #{endTime}
AND t.activity_time >= #{activityBeginTime}
AND t.activity_time <= #{activityEndTime}

    AND (t.title LIKE #{keywordLike} ESCAPE '!'
      OR t.content_text LIKE #{keywordLike} ESCAPE '!'
      OR u.nick_name LIKE #{keywordLike} ESCAPE '!')

ORDER BY t.is_pinned DESC, t.last_activity_time DESC, t.topic_id DESC

mapper.update:
UPDATE biz_research_resource SET del_flag='2', update_by=#{updateBy}, update_time=NOW()
WHERE post_id=#{postId} AND del_flag='0'
AND resource_type=#{resourceType}

UPDATE biz_research_notice_recipient
SET read_flag='Y',read_time=COALESCE(read_time,NOW()),update_time=NOW()
WHERE recipient_id=#{recipientId} AND user_id=#{userId}
